parameters.query:
SELECT bs.*,
  CASE WHEN bs.circuit_open AND bs.circuit_opened_at < now() - interval '10 minutes' THEN true ELSE false END as should_auto_reset
FROM budget_state bs WHERE bs.id = 1;

parameters.jsCode:
const budget = $('Read Budget State').first().json;
const stats = $input.item.json;
const dailyLimit = parseFloat($env.GILBERT_DAILY_BUDGET_USD || '2.0');
const monthlyLimit = parseFloat($env.GILBERT_MONTHLY_BUDGET_USD || '30.0');

const dailySpend = parseFloat(budget.daily_spend_usd || 0);
const monthlySpend = parseFloat(budget.monthly_spend_usd || 0);
const shouldAutoReset = budget.should_auto_reset || false;

const alerts = [];

// Daily budget alerts
if (dailySpend >= dailyLimit) {
  alerts.push('\u26a0\ufe0f Daily budget EXCEEDED: $' + dailySpend.toFixed(4) + ' / $' + dailyLimit.toFixed(2));
} else if (dailySpend >= dailyLimit * 0.8) {
  alerts.push('\u26a0\ufe0f Daily budget at 80%: $' + dailySpend.toFixed(4) + ' / $' + dailyLimit.toFixed(2));
}

// Monthly budget alerts
if (monthlySpend >= monthlyLimit) {
  alerts.push('\u26a0\ufe0f Monthly budget EXCEEDED: $' + monthlySpend.toFixed(4) + ' / $' + monthlyLimit.toFixed(2));
} else if (monthlySpend >= monthlyLimit * 0.8) {
  alerts.push('\u26a0\ufe0f Monthly budget at 80%: $' + monthlySpend.toFixed(4) + ' / $' + monthlyLimit.toFixed(2));
}

// Circuit breaker
if (budget.circuit_open) {
  if (shouldAutoReset) {
    alerts.push('\u2705 Circuit breaker auto-reset (was open for 10+ min)');
  } else {
    alerts.push('\u274c Circuit breaker OPEN (' + (budget.consecutive_failures || 0) + ' consecutive failures)');
  }
}

// Build summary
const successCalls = parseInt(stats.success_calls || 0, 10);
const failedCalls = parseInt(stats.failed_calls || 0, 10);
const totalCost = parseFloat(stats.total_cost || 0);

let message = '';
let subject = '';
if (alerts.length > 0) {
  subject = 'Budget Alert: ' + (dailySpend >= dailyLimit ? 'EXCEEDED' : monthlySpend >= monthlyLimit ? 'EXCEEDED' : budget.circuit_open ? 'Circuit Breaker' : '80% Warning');
  message = '<html><body>';
  message += '<h2>Gilbert Budget Monitor</h2>';
  message += '<p>' + alerts.join('<br>') + '</p>';
  message += '<p><strong>Today:</strong> ' + successCalls + ' calls, ' + failedCalls + ' failures, $' + totalCost.toFixed(4) + ' spent<br>';
  message += '<strong>Monthly:</strong> ' + (budget.monthly_calls || 0) + ' calls, $' + monthlySpend.toFixed(4) + ' spent</p>';
  message += '</body></html>';
}

return [{ json: {
  has_alert: alerts.length > 0,
  message,
  subject,
  should_auto_reset: shouldAutoReset
}}];
